actions.script:
const lists = ['open', 'mine', 'reported', 'watching', 'unassigned', 'week', 'overdue', 'recent', 'done', 'all']
if (!lists.includes(list)) list = 'open'
rowList = []; rowCount = 0; pageMaxIndex = 0; pageRangeLow = 0; pageRangeHigh = 0; counts = {}; keyMatch = null; totals = {}
for (const key of lists) counts[key] = 0
const cf = ec.entity.conditionFactory
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const all = !!vis.allProjects
const visibleIds = Array.from(vis.visibleProjectIds || [])
if (!all && !visibleIds.length) return
const me = vis.userPartyId || null
const split = (value) => value == null || value === '' ? [] : (Array.isArray(value) ? value : String(value).split(',')).map((id) => String(id).trim()).filter((id) => id)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
const nowMillis = toMillis(ec.user.nowTimestamp)
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const dayStart = (text) => toMillis(ec.l10n.parseTimestamp(text + ' 00:00:00.000', pattern))
const todayStart = dayStart(dayText(nowMillis))
let weekEnd = todayStart
for (let i = 0; i < 7; i++) weekEnd = dayStart(dayText(weekEnd + 30 * 3600000))
const current = () => cf.makeConditionDate('fromDate', 'thruDate', null)
const idsOf = (rows, field) => Array.from(new Set(Array.from(rows).map((row) => row[field || 'workEffortId'])))
const partyIdsOf = (role, partyIds) => idsOf(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('partyId', 'in', partyIds)
        .condition('roleTypeId', role).condition(current()).condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true))
        .selectField('workEffortId').list())

// the base: the visible items of projects that are not templates
const base = [cf.makeCondition('workEffortTypeEnumId', 'equals', 'WetTask'), cf.makeCondition('rootWorkEffortId', 'is-not-null', null)]
// never a confidential issue's task the user is no Owner of, a project's manager included (HiddenItems.js)
const notHidden = ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').condition(vis)
if (notHidden) base.push(notHidden)
if (rootWorkEffortId) base.push(cf.makeCondition('rootWorkEffortId', 'equals', rootWorkEffortId))
if (!all) {
    base.push(cf.makeCondition('rootWorkEffortId', 'in', visibleIds))
    const restrictedOk = [cf.makeCondition('visibilityEnumId', 'is-null', null),
        cf.makeCondition('visibilityEnumId', 'not-in', ['WevRestricted', 'WevConfidential'])]
    const managed = Array.from(vis.managedProjectIds || [])
    const restricted = Array.from(vis.restrictedItemIds || [])
    if (managed.length) restrictedOk.push(cf.makeCondition('rootWorkEffortId', 'in', managed))
    if (restricted.length) restrictedOk.push(cf.makeCondition('workEffortId', 'in', restricted))
    base.push(cf.makeCondition(restrictedOk, 'or'))
    // a client contact: the items shared with it only (impl-projects.md P10)
    if (vis.itemVisibilityIds) base.push(cf.makeCondition('visibilityEnumId', 'in', Array.from(vis.itemVisibilityIds)))
}
const templateIds = idsOf(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetProject')
        .condition('isTemplate', 'Y').selectField('workEffortId').list())
if (templateIds.length) base.push(cf.makeCondition('rootWorkEffortId', 'not-in', templateIds))

// the smart lists' conditions
const openCond = cf.makeCondition('statusId', 'not-in', ['WeComplete', 'WeClosed', 'WeCancelled'])
const doneCond = cf.makeCondition('statusId', 'in', ['WeComplete', 'WeClosed'])
const none = cf.makeCondition('workEffortId', 'equals', '_NONE_')
const inIds = (ids) => ids.length ? cf.makeCondition('workEffortId', 'in', ids) : none
const mine = me ? partyIdsOf('Assignee', [me]) : []
const reported = me ? Array.from(new Set(partyIdsOf('Reporter', [me]).concat(idsOf(ec.entity.find('mantle.work.effort.WorkEffort')
        .condition('ownerPartyId', me).condition('workEffortTypeEnumId', 'WetTask').selectField('workEffortId').list())))) : []
const watching = me ? Array.from(new Set(partyIdsOf('Watcher', [me]).concat(idsOf(ec.entity.find('mantle.party.communication.RecordFollower')
        .condition('recordEntityName', 'mantle.work.effort.WorkEffort').condition('userId', ec.user.userId).selectField('recordId').list(), 'recordId')))) : []
const listConds = {
    open: [openCond], all: [], done: [doneCond],
    mine: [openCond, inIds(mine)], reported: [openCond, inIds(reported)], watching: [openCond, inIds(watching)],
    week: [openCond, cf.makeCondition('estimatedCompletionDate', 'greater-equals', new Date(todayStart)),
        cf.makeCondition('estimatedCompletionDate', 'less-than', new Date(weekEnd))],
    overdue: [openCond, cf.makeCondition('estimatedCompletionDate', 'less-than', new Date(todayStart))],
    recent: [cf.makeCondition('lastUpdatedStamp', 'greater-equals', new Date(nowMillis - 7 * 86400000))],
}
const unassignedCond = () => {
    const assigned = idsOf(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('roleTypeId', 'Assignee').condition(current())
            .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true))
            .condition('workEffortId', 'in', idsOf(ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition(base.concat([openCond]), 'and'))
                .selectField('workEffortId').list())).selectField('workEffortId').list())
    return assigned.length ? cf.makeCondition('workEffortId', 'not-in', assigned) : null
}
const unassigned = unassignedCond()
listConds.unassigned = [openCond].concat(unassigned ? [unassigned] : [])
const countOf = (conds) => ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition(base.concat(conds), 'and')).count()
if (withCounts) for (const key of lists) counts[key] = countOf(listConds[key])

// the find
const find = []
const statusIds = split(statusId)
if (statusIds.length) find.push(cf.makeCondition('statusId', 'in', statusIds))
const conds = (statusIds.length ? listConds[list].filter((cond) => cond !== openCond && cond !== doneCond) : listConds[list]).concat(find)
const words = text ? String(text).trim() : ''
if (words) {
    const key = words.toUpperCase()
    const exact = /^[A-Z0-9]{1,8}-\d+$/.test(key) ? ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition(base, 'and'))
            .condition('workEffortId', key).one() : null
    if (exact) { keyMatch = exact.workEffortId; conds.push(cf.makeCondition('workEffortId', 'equals', exact.workEffortId)) }
    else conds.push(cf.makeCondition([cf.makeCondition('workEffortName', 'like', `%${words}%`, false, true),
        cf.makeCondition('workEffortId', 'like', `%${words}%`, false, true), cf.makeCondition('description', 'like', `%${words}%`, false, true)], 'or'))
}
const purposes = split(purposeEnumId)
if (purposes.length) conds.push(cf.makeCondition('purposeEnumId', 'in', purposes))
const bands = {high: [1, 3], normal: [4, 6], low: [7, 9]}
if (bands[priorityBand]) {
    conds.push(cf.makeCondition('priority', 'greater-equals', bands[priorityBand][0]))
    conds.push(cf.makeCondition('priority', 'less-equals', bands[priorityBand][1]))
}
const assignees = split(assigneePartyId)
if (assignees.length) conds.push(inIds(partyIdsOf('Assignee', assignees)))
if (reporterPartyId) conds.push(cf.makeCondition([cf.makeCondition('ownerPartyId', 'equals', reporterPartyId),
    inIds(partyIdsOf('Reporter', [reporterPartyId]))], 'or'))
const memberOf = (planId, type) => idsOf(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', planId)
        .condition('workEffortAssocTypeEnumId', type).condition(current()).selectField('toWorkEffortId').list(), 'toWorkEffortId')
if (milestoneId) conds.push(inIds(memberOf(milestoneId, 'WeatMilestone')))
if (releaseId) conds.push(inIds(memberOf(releaseId, 'WeatRelease')))
if (sprintId) {
    let sprintIds = split(sprintId)
    if (sprintIds.includes('current')) {
        let active = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetSprint').condition('statusId', 'WeInProgress')
        if (rootWorkEffortId) active = active.condition('rootWorkEffortId', rootWorkEffortId)
        else if (!all) active = active.condition('rootWorkEffortId', 'in', visibleIds)
        sprintIds = sprintIds.filter((id) => id !== 'current').concat(idsOf(active.selectField('workEffortId').list()))
    }
    conds.push(inIds(Array.from(new Set(sprintIds.flatMap((id) => memberOf(id, 'WeatSprint'))))))
}
if (labelId) conds.push(inIds(idsOf(ec.entity.find('mantle.work.effort.WorkEffortCategoryAppl').condition('workEffortCategoryId', 'in', split(labelId))
        .selectField('workEffortId').list())))
if (parentWorkEffortId) conds.push(cf.makeCondition('parentWorkEffortId', 'equals', parentWorkEffortId))
else if (topLevel === 'Y' || topLevel === 'true' || topLevel === true) conds.push(cf.makeCondition('parentWorkEffortId', 'is-null', null))
if (underWorkEffortId) {
    const under = []
    const queue = [underWorkEffortId]
    for (let i = 0; i < queue.length && i < 20000; i++) for (const child of ec.entity.find('mantle.work.effort.WorkEffort')
            .condition('parentWorkEffortId', queue[i]).selectField('workEffortId').list()) {
        if (under.includes(child.workEffortId)) continue
        under.push(child.workEffortId); queue.push(child.workEffortId)
    }
    conds.push(inIds(under))
}
if (visibilityEnumId) conds.push(cf.makeCondition('visibilityEnumId', 'equals', visibilityEnumId))
if (recurring === 'Y') {
    const series = idsOf(ec.entity.find('mantle.work.effort.WorkEffortRecurrence').selectField('workEffortId').list())
    const instances = idsOf(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance')
            .selectField('toWorkEffortId').list(), 'toWorkEffortId')
    conds.push(inIds(Array.from(new Set(series.concat(instances)))))
}
if (dueFrom != null) conds.push(cf.makeCondition('estimatedCompletionDate', 'greater-equals', dueFrom))
if (dueThru != null) conds.push(cf.makeCondition('estimatedCompletionDate', 'less-than', dueThru))

const condition = cf.makeCondition(base.concat(conds), 'and')
rowCount = ec.entity.find('mantle.work.effort.WorkEffort').condition(condition).count()
// the sums below the list: every row of the find (up to 5000), not the page
const sums = {estimated: 0, remaining: 0, actual: 0}
if (!parentWorkEffortId) for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition(condition).selectField('estimatedWorkTime')
        .selectField('remainingWorkTime').selectField('actualWorkTime').limit(5000).list()) {
    sums.estimated += Number(String(row.estimatedWorkTime ?? 0)); sums.remaining += Number(String(row.remainingWorkTime ?? 0))
    sums.actual += Number(String(row.actualWorkTime ?? 0))
}
const hoursText = (value) => ec.l10n.format(Math.round(value * 100) / 100, '#,##0.##')
totals = {estimatedText: hoursText(sums.estimated), remainingText: hoursText(sums.remaining), actualText: hoursText(sums.actual)}
const sortable = ['workEffortId', 'workEffortName', 'statusId', 'priority', 'estimatedCompletionDate', 'sequenceNum', 'lastUpdatedStamp',
    'rootWorkEffortId', 'purposeEnumId', 'estimatedWorkTime', 'remainingWorkTime', 'actualWorkTime']
const orderField = orderByField ? String(orderByField).replace(/^[+^]/, '') : ''
let orderBy
if (orderField && sortable.includes(orderField.replace(/^-/, ''))) orderBy = [orderField, 'workEffortId']
else if (treeOrder || parentWorkEffortId) orderBy = ['sequenceNum', 'workEffortId']
else if (list === 'recent') orderBy = ['-lastUpdatedStamp', 'workEffortId']
else if (list === 'done') orderBy = ['-actualCompletionDate', 'workEffortId']
else orderBy = ['priority', 'estimatedCompletionDate', 'workEffortId']
const size = pageNoLimit ? Math.max(1, Math.min(rowCount, 2000)) : Math.max(1, Math.min(Number(pageSize) || 25, 200))
pageSize = size
pageMaxIndex = rowCount ? Math.floor((rowCount - 1) / size) : 0
pageIndex = pageNoLimit ? 0 : Math.min(Math.max(0, Number(pageIndex) || 0), pageMaxIndex)
let rows = ec.entity.find('mantle.work.effort.WorkEffort').condition(condition)
for (const field of orderBy) rows = rows.orderBy(field)
const page = Array.from(rows.offset(pageIndex * size).limit(size).list()).map((row) => row.getMap())
pageRangeLow = rowCount ? pageIndex * size + 1 : 0
pageRangeHigh = Math.min((pageIndex + 1) * size, rowCount)
rowList = ec.service.sync().name('ironstone.projects.WorkItemServices.decorate#WorkItemRows').parameters({taskList: page, visibleInfo: vis}).call()?.rowList || []

rowList = []
const tasks = Array.from(taskList || [])
if (!tasks.length) return
const cf = ec.entity.conditionFactory
const L = (text) => ec.l10n.localize(text)
const vis = visibleInfo || ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const me = vis.userPartyId || null
const members = new Set(Array.from(vis.memberProjectIds || []))
const managed = new Set(Array.from(vis.managedProjectIds || []))
const projectsManager = ec.user.isInGroup('BOSS_PROJECT_MANAGER')
const ids = tasks.map((task) => task.workEffortId)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const fmt = (millis, format) => ec.l10n.format(new Date(Number(millis)), format)
const nowMillis = toMillis(ec.user.nowTimestamp)
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const todayStart = toMillis(ec.l10n.parseTimestamp(dayText(nowMillis) + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'))
const tomorrowStart = toMillis(ec.l10n.parseTimestamp(dayText(todayStart + 30 * 3600000) + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'))
const thisYear = fmt(nowMillis, 'yyyy')
const hours = (value) => value == null || value === '' ? '' : ec.l10n.format(value, '#,##0.##')
const icons = {WepTask: 'sym_o_task_alt', WepFix: 'sym_o_bug_report', WepNewFeature: 'sym_o_new_releases', WepFeatureEnhance: 'sym_o_trending_up',
    WepFeatureTest: 'sym_o_science', WepDocument: 'sym_o_description', WepSupport: 'sym_o_support_agent', WepResearch: 'sym_o_travel_explore',
    WepDeployment: 'sym_o_rocket_launch', WepDevelopment: 'sym_o_code', WepToDo: 'sym_o_check_box', WepCommunication: 'sym_o_forum',
    WepPlaceholder: 'sym_o_crop_free'}
const enumLabel = (id) => id ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()?.description || id) : ''
const statusLabel = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id) : ''
const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: Array.from(new Set(tasks.map((task) => task.statusId).filter((id) => id)))}).call()?.colors || {}
const partyName = (party) => party ? (party.organizationName || [party.firstName, party.lastName].filter((name) => name).join(' ') || party.pseudoId || party.partyId) : null

// the projects and parents by name
const names = {}
const otherIds = Array.from(new Set(tasks.map((task) => task.rootWorkEffortId).concat(tasks.map((task) => task.parentWorkEffortId)).filter((id) => id)))
if (otherIds.length) for (const row of ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').without(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', otherIds), vis)
        .selectField('workEffortId').selectField('workEffortName').list()) names[row.workEffortId] = row.workEffortName || row.workEffortId
// the assignees
const assignees = {}
const partyIds = new Set()
for (const wep of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', 'in', ids).condition('roleTypeId', 'Assignee')
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true))
        .orderBy('fromDate').list()) {
    const list = assignees[wep.workEffortId] || (assignees[wep.workEffortId] = [])
    if (!list.includes(wep.partyId)) list.push(wep.partyId)
    partyIds.add(wep.partyId)
}
const partyNames = {}
if (partyIds.size) for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', Array.from(partyIds)).list())
    partyNames[party.partyId] = party.privateOwnerUserId && party.privateOwnerUserId !== ec.user.userId ? party.partyId : partyName(party)
// the milestone and release (current memberships), the labels
const plans = {}
for (const assoc of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', 'in', ids)
        .condition('workEffortAssocTypeEnumId', 'in', ['WeatMilestone', 'WeatRelease', 'WeatSprint', 'WeatComponent'])
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list()) {
    const entry = plans[assoc.toWorkEffortId] || (plans[assoc.toWorkEffortId] = {})
    entry[assoc.workEffortAssocTypeEnumId] = assoc.workEffortId
}
const planIds = Array.from(new Set(Object.values(plans).flatMap((entry) => Object.values(entry))))
if (planIds.length) for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', planIds)
        .selectField('workEffortId').selectField('workEffortName').list()) names[row.workEffortId] = row.workEffortName || row.workEffortId
const labels = {}
const appls = Array.from(ec.entity.find('mantle.work.effort.WorkEffortCategoryAppl').condition('workEffortId', 'in', ids).list())
const labelRows = {}
const labelIds = Array.from(new Set(appls.map((appl) => appl.workEffortCategoryId)))
if (labelIds.length) for (const row of ec.entity.find('mantle.work.effort.WorkEffortCategory').condition('workEffortCategoryId', 'in', labelIds)
        .condition('categoryTypeEnumId', 'WcatLabel').list()) labelRows[row.workEffortCategoryId] = row
for (const appl of appls) {
    const label = labelRows[appl.workEffortCategoryId]
    if (!label) continue
    ;(labels[appl.workEffortId] || (labels[appl.workEffortId] = [])).push({labelId: label.workEffortCategoryId, label: label.description || label.workEffortCategoryId,
        colorName: label.colorName || 'grey'})
}
// repeating: a series or an instance of one
const recurring = new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortRecurrence').condition('workEffortId', 'in', ids).list()).map((row) => row.workEffortId))
for (const link of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', 'in', ids)
        .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').list()) recurring.add(link.toWorkEffortId)
// the roll-ups of the subtrees
const rollups = {}
try {
    for (const row of ec.service.sync().name('mantle.work.ProjectServices.get#WorkItemTree').parameters({workEffortIds: ids}).call()?.workItemList || [])
        rollups[row.workEffortId] = row
} catch (err) {
    ec.logger.error(`Work items: no roll-ups for ${ids.length} rows: ${err && err.message ? err.message : err}`)
}

for (const task of tasks) {
    const id = task.workEffortId
    const isDone = ['WeComplete', 'WeClosed'].includes(task.statusId)
    const isOpen = !isDone && task.statusId !== 'WeCancelled'
    const due = toMillis(task.estimatedCompletionDate)
    let dueText = ''
    if (due != null) {
        dueText = due >= todayStart && due < tomorrowStart ? L('Today') : fmt(due, fmt(due, 'yyyy') === thisYear ? 'MMM d' : 'MMM d, yyyy')
    }
    const plan = plans[id] || {}
    const others = (assignees[id] || []).map((partyId) => partyNames[partyId] || partyId)
    const rollup = rollups[id] || {}
    const myRoles = me && (assignees[id] || []).includes(me)
    const canUpdate = !!vis.allProjects || (me && task.ownerPartyId === me) || myRoles || members.has(task.rootWorkEffortId)
            || managed.has(task.rootWorkEffortId) || projectsManager
    rowList.push({workEffortId: id, workEffortName: task.workEffortName || id,
        url: '/qapps/Projects/WorkItems/WorkItemDetail?workEffortId=' + encodeURIComponent(id),
        purposeEnumId: task.purposeEnumId || null, purposeLabel: enumLabel(task.purposeEnumId), typeIcon: icons[task.purposeEnumId] || 'sym_o_task_alt',
        statusId: task.statusId || null, statusLabel: statusLabel(task.statusId), statusColor: colors[task.statusId] || 'grey-7',
        isDone: isDone, isOpen: isOpen, canUpdate: !!canUpdate,
        rootWorkEffortId: task.rootWorkEffortId || null, projectName: task.rootWorkEffortId ? (names[task.rootWorkEffortId] || task.rootWorkEffortId) : '',
        parentWorkEffortId: task.parentWorkEffortId || null, parentName: task.parentWorkEffortId ? (names[task.parentWorkEffortId] || task.parentWorkEffortId) : '',
        priority: task.priority ?? null, priorityText: task.priority != null ? String(task.priority) : '',
        assigneePartyId: (assignees[id] || [])[0] || null, assigneeText: others.join(', '),
        milestoneId: plan.WeatMilestone || null, milestoneName: plan.WeatMilestone ? names[plan.WeatMilestone] : '',
        releaseId: plan.WeatRelease || null, releaseName: plan.WeatRelease ? names[plan.WeatRelease] : '',
        sprintId: plan.WeatSprint || null, sprintName: plan.WeatSprint ? names[plan.WeatSprint] : '',
        componentId: plan.WeatComponent || null, componentName: plan.WeatComponent ? names[plan.WeatComponent] : '',
        labelList: labels[id] || [], labelText: (labels[id] || []).map((label) => label.label).join(', '),
        estimatedCompletionDate: due != null ? dayText(due) : null, dueAllDay: 'Y', dueText: dueText, dueEditText: due != null ? dayText(due) : '',
        overdue: isOpen && due != null && due < todayStart,
        estimatedWorkTime: task.estimatedWorkTime ?? null, remainingWorkTime: task.remainingWorkTime ?? null, actualWorkTime: task.actualWorkTime ?? null,
        estimatedText: hours(task.estimatedWorkTime), remainingText: hours(task.remainingWorkTime), actualText: hours(task.actualWorkTime),
        estimatedPoints: task.estimatedPoints ?? null, pointsText: hours(task.estimatedPoints), sequenceNum: task.sequenceNum ?? null, isRecurring: recurring.has(id),
        visibilityEnumId: task.visibilityEnumId || null,
        childCount: rollup.childCount ?? 0, totalEstimatedWorkTime: rollup.totalEstimatedWorkTime ?? null,
        totalRemainingWorkTime: rollup.totalRemainingWorkTime ?? null, totalActualWorkTime: rollup.totalActualWorkTime ?? null,
        totalEstimatedText: hours(rollup.totalEstimatedWorkTime), totalRemainingText: hours(rollup.totalRemainingWorkTime),
        totalActualText: hours(rollup.totalActualWorkTime), percentDone: rollup.percentDone ?? null,
        doneOfTotal: rollup.itemCount ? rollup.doneCount + '/' + rollup.itemCount : '',
        updatedText: task.lastUpdatedStamp ? fmt(toMillis(task.lastUpdatedStamp), 'MMM d') : ''})
    // the text a view shows for a field (m-list-views reads field_display): a tree row fetched later has no cells
    const row = rowList[rowList.length - 1]
    Object.assign(row, {purposeEnumId_display: row.purposeLabel, statusId_display: row.statusLabel, assigneePartyId_display: row.assigneeText,
        rootWorkEffortId_display: row.projectName, parentWorkEffortId_display: row.parentWorkEffortId ? row.parentWorkEffortId + ' ' + row.parentName : '',
