for (let guard = 0; at && guard < 200; guard++) { chain.unshift(at); at = find(at.parentWorkEffortId) }
const project = find(item.rootWorkEffortId)
if (project) breadcrumbList.push({workEffortId: project.workEffortId, label: project.workEffortName || project.workEffortId,
    url: '/qapps/Projects/Projects/ProjectDetail?workEffortId=' + encodeURIComponent(project.workEffortId), isProject: true})
for (const ancestor of chain) breadcrumbList.push({workEffortId: ancestor.workEffortId, label: ancestor.workEffortId + ' ' + (ancestor.workEffortName || ''),
    url: path + encodeURIComponent(ancestor.workEffortId), isProject: false})
// plan items, labels
planItems = {}
for (const assoc of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'in', ['WeatMilestone', 'WeatRelease', 'WeatSprint', 'WeatComponent'])
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list()) {
    const plan = find(assoc.workEffortId)
    const key = {WeatMilestone: 'milestone', WeatRelease: 'release', WeatSprint: 'sprint', WeatComponent: 'component'}[assoc.workEffortAssocTypeEnumId]
    planItems[key] = {workEffortId: assoc.workEffortId, name: plan?.workEffortName || assoc.workEffortId}
}
labelList = []
for (const appl of ec.entity.find('mantle.work.effort.WorkEffortCategoryAppl').condition('workEffortId', workEffortId).list()) {
    const label = ec.entity.find('mantle.work.effort.WorkEffortCategory').condition('workEffortCategoryId', appl.workEffortCategoryId).one()
    if (label?.categoryTypeEnumId === 'WcatLabel') labelList.push({labelId: label.workEffortCategoryId, label: label.description || label.workEffortCategoryId,
        colorName: label.colorName || 'grey'})
}
// the roll-up and the sub-items
const tree = (parameters) => ec.service.sync().name('mantle.work.ProjectServices.get#WorkItemTree').parameters(parameters).call() || {}
const own = Array.from(tree({workEffortIds: [workEffortId]}).workItemList || [])[0] || {}
rollup = {childCount: own.childCount || 0, estimatedText: hours(item.estimatedWorkTime), remainingText: hours(item.remainingWorkTime),
    actualText: hours(item.actualWorkTime), pointsText: hours(item.estimatedPoints), budgetText: hours(item.totalTimeAllowed),
    totalEstimatedText: hours(own.totalEstimatedWorkTime), totalRemainingText: hours(own.totalRemainingWorkTime), totalActualText: hours(own.totalActualWorkTime),
    totalBudgetText: hours(own.totalBudget), itemCount: own.itemCount || 0, doneCount: own.doneCount || 0, percentDone: own.percentDone}
// a client contact (impl-projects.md P10b): the hours logged only when the project shares its hours with it
if (ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')) {
    let shareHours = []
    ec.message.pushErrors()
    try { shareHours = Array.from(ec.service.sync().name('mantle.work.ProjectServices.get#ClientProjectInfo').call()?.shareHoursProjectIds || []) }
    catch (err) { shareHours = [] } finally { ec.message.clearErrors(); ec.message.popErrors() }
    if (!shareHours.includes(item.rootWorkEffortId)) Object.assign(rollup, {actualText: '', totalActualText: '', budgetText: '', totalBudgetText: ''})
}
const level = tree({parentWorkEffortId: workEffortId})
const decorated = {}
const rows = Array.from(level.workItemList || [])
if (rows.length) for (const row of ec.service.sync().name('ironstone.projects.WorkItemServices.decorate#WorkItemRows').parameters({taskList: rows}).call()?.rowList || [])
    decorated[row.workEffortId] = row
subItemList = rows.map((row) => Object.assign({}, decorated[row.workEffortId] || {}, {parentWorkEffortId: row.parentWorkEffortId}))
subItemTotals = Object.assign({}, level.totals || {}, {totalEstimatedText: hours(level.totals?.totalEstimatedWorkTime),
    totalRemainingText: hours(level.totals?.totalRemainingWorkTime), totalActualText: hours(level.totals?.totalActualWorkTime)})
// relations both ways: the kind as this item reads it
const kinds = {WeatDependsOn: ['Blocked by', 'Blocks'], WeatRelatesTo: ['Relates to', 'Relates to'], WeatDuplicates: ['Duplicates', 'Duplicated by'],
    WeatCausedBy: ['Caused by', 'Causes'], WeatClone: ['Clones', 'Cloned by'], WeatBasedOn: ['Based on', 'Basis of'], WeatIndependentOf: ['Independent of', 'Independent of']}
relationList = []
const statusLabel = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id) : ''
const hiddenItems = ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js')
const addRelation = (assoc, otherId, outward) => {
    // a relation to a confidential issue's task the user is no Owner of is not shown
    const other = hiddenItems.shown(otherId) ? find(otherId) : null
    if (other == null) return
    relationList.push({workEffortId: assoc.workEffortId, toWorkEffortId: assoc.toWorkEffortId, workEffortAssocTypeEnumId: assoc.workEffortAssocTypeEnumId,
        fromDate: assoc.fromDate, kindText: ec.l10n.localize(kinds[assoc.workEffortAssocTypeEnumId][outward ? 0 : 1]),
        otherId: otherId, otherName: other.workEffortName || otherId, otherStatus: statusLabel(other.statusId),
        otherUrl: other.workEffortTypeEnumId === 'WetTask' ? path + encodeURIComponent(otherId) : null,
        lagText: assoc.workEffortAssocTypeEnumId === 'WeatDependsOn' && assoc.lagDays != null ? hours(assoc.lagDays) : ''})
}
for (const assoc of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'in', Object.keys(kinds)).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
    addRelation(assoc, assoc.toWorkEffortId, true)
for (const assoc of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'in', Object.keys(kinds)).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
    addRelation(assoc, assoc.workEffortId, false)
// the requests it serves
requestList = []
for (const link of ec.entity.find('mantle.request.RequestWorkEffort').condition('workEffortId', workEffortId).list()) {
    const request = ec.entity.find('mantle.request.Request').condition('requestId', link.requestId).one()
    // a confidential case is not shown on its task (impl-people P21)
    if (request && request.requestTypeEnumId !== 'RqtHrCase') requestList.push({requestId: request.requestId, requestName: request.requestName || request.requestId, statusText: statusLabel(request.statusId),
        url: '/qapps/Projects/Requests/RequestDetail?requestId=' + encodeURIComponent(request.requestId)})
}
// the repeat rule: the item's, or its series'
recurrence = null
let seriesId = workEffortId
let rule = ec.entity.find('mantle.work.effort.WorkEffortRecurrence').condition('workEffortId', workEffortId).one()
if (rule == null) {
    const link = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
            .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').list())[0]
    if (link) { seriesId = link.workEffortId; rule = ec.entity.find('mantle.work.effort.WorkEffortRecurrence').condition('workEffortId', seriesId).one() }
}
if (rule?.rrule) recurrence = {seriesWorkEffortId: seriesId, rrule: rule.rrule, recurFromCompletion: rule.recurFromCompletion === 'Y',
    text: ec.service.sync().name('ironstone.projects.WorkItemServices.describe#RepeatRule').parameters({rrule: rule.rrule,
        recurFromCompletion: rule.recurFromCompletion}).call()?.text || rule.rrule}
// a task that is an issue of a repository: its number, its public page and its outward conversation
issue = null
// (Mantle's get#TaskIssue: empty for a task that is no issue's, and for a confidential one the user is no Owner of)
const taskIssue = ec.service.sync().name('mantle.smithy.SmithyIssueServices.get#TaskIssue').parameters({workEffortId: workEffortId}).call() || {}
if (taskIssue.issueNumber) {
    const number = Number(taskIssue.issueNumber)
    issue = {issueNumber: number, numberText: '#' + number, repositoryPath: taskIssue.repositoryPath, confidential: !!taskIssue.confidential,
        pageUrl: taskIssue.publicUrl || null, postList: [], hasMore: false, readable: false}
    // the posts Mantle's forum lets this user read of the issue's topic; a refusal leaves the box empty
    ec.message.pushErrors()
    try {
        const posts = ec.service.sync().name('mantle.forum.ForumServices.get#Posts')
                .parameters({input: {siteId: taskIssue.siteId, rootCommEventId: taskIssue.rootCommEventId, limit: 50}}).call()?.result
        if (!ec.message.hasError() && posts) {
            issue.readable = true
            issue.hasMore = !!posts.nextCursor
            issue.postList = Array.from(posts.postList || []).map((post) => ({postId: post.postId,
                authorName: post.author?.displayName || (post.author?.handle ? '@' + post.author.handle : ec.l10n.localize('Community member')),
                dateText: post.entryDate ? ec.l10n.format(post.entryDate, 'yyyy-MM-dd HH:mm') : '',
                markText: post.postKind === 'event' ? ec.l10n.localize('state change') : post.visibility === 'staff' ? ec.l10n.localize('Owners only')
                    : post.visibility === 'pending' ? ec.l10n.localize('waiting for review') : post.hasHistory ? ec.l10n.localize('edited') : '',
                bodyHtml: post.body || ''}))
        }
    } catch (err) {
        issue.readable = false
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

const L = (value) => ec.l10n.localize(value)
const parts = {}
for (const part of String(rrule).replace(/^RRULE:/i, '').split(';')) { const [key, value] = part.split('='); if (key) parts[key.toUpperCase()] = value || '' }
const interval = Number(parts.INTERVAL || 1)
const units = {DAILY: ['day', 'days'], WEEKLY: ['week', 'weeks'], MONTHLY: ['month', 'months'], YEARLY: ['year', 'years']}[parts.FREQ]
if (!units) { text = rrule; return }
const ordinal = (n) => { const v = n % 100; return n + (v >= 11 && v <= 13 ? 'th' : ({1: 'st', 2: 'nd', 3: 'rd'}[n % 10] || 'th')) }
const dayNames = {MO: 'Monday', TU: 'Tuesday', WE: 'Wednesday', TH: 'Thursday', FR: 'Friday', SA: 'Saturday', SU: 'Sunday'}
let words = interval > 1 ? `${L('Every')} ${interval} ${L(units[1])}` : `${L('Every')} ${L(units[0])}`
if (parts.BYDAY) words += ' ' + L('on') + ' ' + parts.BYDAY.split(',').map((day) => L(dayNames[day.replace(/^[-+]?\d+/, '')] || day)).join(', ')
if (parts.BYMONTHDAY) words += ' ' + L('on the') + ' ' + parts.BYMONTHDAY.split(',').map((day) => Number(day) === -1 ? L('last day') : ordinal(Number(day))).join(', ')
if (parts.COUNT) words += ', ' + ec.resource.expand('${count} times', '', {count: parts.COUNT})
if (parts.UNTIL) words += ', ' + L('until') + ' ' + parts.UNTIL.substring(0, 4) + '-' + parts.UNTIL.substring(4, 6) + '-' + parts.UNTIL.substring(6, 8)
text = words + '; ' + (recurFromCompletion === 'Y' ? L('counted from the day one is completed') : L('next made on completion'))

// kind: [assoc type, this item is the assoc's workEffortId]
const kinds = {blockedBy: ['WeatDependsOn', true], blocks: ['WeatDependsOn', false], relatesTo: ['WeatRelatesTo', true],
    duplicates: ['WeatDuplicates', true], duplicatedBy: ['WeatDuplicates', false], causedBy: ['WeatCausedBy', true], causes: ['WeatCausedBy', false],
    clones: ['WeatClone', true], clonedBy: ['WeatClone', false], basedOn: ['WeatBasedOn', true]}
const entry = kinds[kind]
if (!entry) { ec.message.addError(ec.resource.expand('${kind} is not a kind of link', '', {kind})); return }
const from = entry[1] ? workEffortId : otherId
const to = entry[1] ? otherId : workEffortId
// a dependency through the Mantle service, which refuses a loop or one in the item's own branch of the tree
if (entry[0] === 'WeatDependsOn') {
    ec.service.sync().name('mantle.work.TaskServices.add#TaskDependency').parameters({workEffortId: from, toWorkEffortId: to, lagDays: lagDays ?? null}).call()
    if (ec.message.hasError()) return
    message = ec.resource.expand('Linked to ${otherId}', '', {otherId})
    return
}
const existing = ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', from).condition('toWorkEffortId', to)
        .condition('workEffortAssocTypeEnumId', entry[0]).conditionDate('fromDate', 'thruDate', null).count()
if (!existing) ec.service.sync().name('create#mantle.work.effort.WorkEffortAssoc').parameters({workEffortId: from, toWorkEffortId: to,
    workEffortAssocTypeEnumId: entry[0], fromDate: ec.user.nowTimestamp, lagDays: entry[0] === 'WeatDependsOn' ? (lagDays ?? null) : null}).call()
if (ec.message.hasError()) return
message = ec.resource.expand('Linked to ${otherId}', '', {otherId})

let rule = ''
if (frequency) {
    if (!['DAILY', 'WEEKLY', 'MONTHLY', 'YEARLY'].includes(frequency)) { ec.message.addError(ec.resource.expand('${frequency} is not a frequency', '', {frequency})); return }
    const parts = ['FREQ=' + frequency]
    if (interval && Number(interval) > 1) parts.push('INTERVAL=' + Number(interval))
    const days = String(byDay || '').split(',').map((day) => day.trim().toUpperCase()).filter((day) => /^(MO|TU|WE|TH|FR|SA|SU)$/.test(day))
    if (days.length && frequency === 'WEEKLY') parts.push('BYDAY=' + days.join(','))
    if (byMonthDay && frequency === 'MONTHLY') {
        const day = Number(byMonthDay)
        if (!Number.isInteger(day) || day === 0 || day < -1 || day > 31) { ec.message.addError(ec.l10n.localize('A day of the month is 1 to 31, or -1 for the last')); return }
        parts.push('BYMONTHDAY=' + day)
    }
    if (count && Number(count) > 0) parts.push('COUNT=' + Number(count))
    else if (until) {
        if (!/^\d{4}-\d{2}-\d{2}$/.test(String(until).trim())) { ec.message.addError(ec.l10n.localize('The end date is yyyy-MM-dd')); return }
        parts.push('UNTIL=' + String(until).trim().replace(/-/g, '') + 'T235959Z')
    }
    rule = parts.join(';')
}
ec.service.sync().name('mantle.work.TaskServices.set#TaskRecurrence').parameters({workEffortId, rrule: rule,
    recurFromCompletion: fromCompletion === 'Y' ? 'Y' : 'N'}).call()
if (ec.message.hasError()) return
message = rule ? ec.service.sync().name('ironstone.projects.WorkItemServices.describe#RepeatRule').parameters({rrule: rule,
    recurFromCompletion: fromCompletion === 'Y' ? 'Y' : 'N'}).call()?.text : ec.l10n.localize('No longer repeats')

// NewProject's Start step with the defaults for the rest (ironstone.projects.ProjectServices.create#NewProject)
const out = ec.service.sync().name('ironstone.projects.ProjectServices.create#NewProject').parameters({workEffortId: workEffortId, workEffortName: workEffortName,
    clientPartyId: clientPartyId || null, templateWorkEffortId: templateWorkEffortId || null}).call() || {}
if (ec.message.hasError()) return
projectId = out.projectId; url = out.url; message = out.message
